function useOrder(){state.orders=Math.max(0,state.orders-1);render();}
function calculateYield(){const total={food:0,wood:0,stone:0,coin:0};for(const row of state.map)for(const t of row){if(t.city){total.food+=2;total.coin+=1+(t.city.level>=2?1:0);total.food-=t.city.pop;}if(t.improvement){if(t.improvement.key==='farm')total.food+=2;if(t.improvement.key==='camp')total.wood+=2;if(t.improvement.key==='quarry')total.stone+=2;}}return total;}
function render(){renderMap();actionMarkup();const y=calculateYield();for(const k of ['food','wood','stone','coin']){$(k+'Val').textContent=state.resources[k];$(k+'Change').textContent=(y[k]>=0?'+':'')+y[k];$(k+'Change').style.color=y[k]<0?'#c16b57':'#558355';}
 $('turnNum').textContent=String(state.turn).padStart(2,'0');$('progressFill').style.width=`${Math.min(100,state.turn/MAX_TURNS*100)}%`;
 const seasons=['Spring','Summer','Autumn','Winter'];$('season').textContent=`${seasons[Math.floor((state.turn-1)/5)%4]} · Year ${Math.ceil(state.turn/5)}`;$('mapMeta').textContent=`DAY ${state.turn} · ${seasons[Math.floor((state.turn-1)/5)%4].toUpperCase()}`;
 $('turnHint').textContent=state.orders===0?'READY TO GROW':`${state.orders} ORDER${state.orders===1?'':'S'} LEFT`;$('endTurn').disabled=state.done;
 const towns=state.map.flat().filter(t=>t.city).length;$('objective').innerHTML=towns>=3?'✦ &nbsp;Three towns founded!':`✦ &nbsp;Grow a kingdom of 3 towns <span style="opacity:.65">(${towns}/3)</span>`;
 $('log').innerHTML=state.log.map(item=>`<li><span>T${String(item.turn).padStart(2,'0')}</span><div>${item.text}</div></li>`).join('')||'<li><span>—</span><div>Your chronicle begins here.</div></li>';
}
function endTurn(){if(state.done)return;const income=calculateYield();for(const k of Object.keys(income))state.resources[k]=Math.max(0,state.resources[k]+income[k]);
 for(const c of state.map.flat().filter(t=>t.city)){const threshold=4+c.city.pop*2;if(state.resources.food>=threshold&&c.city.pop<6){state.resources.food-=threshold;c.city.pop++;addLog(`<strong>${c.city.name}</strong> welcomed a new family. Population is now ${c.city.pop}.`);}}
 const events={5:['A golden summer! The market brings a little extra coin.',{coin:2}],10:['Travelers pass through, sharing a generous harvest.',{food:3}],15:['A master builder visits your towns. Finders keepers!',{wood:2,stone:1}],20:['A bright harvest festival closes the year in style.',{food:2,coin:2}]};
 if(events[state.turn]){const [text,gift]=events[state.turn];Object.entries(gift).forEach(([k,v])=>state.resources[k]+=v);addLog(text);}
 if(state.turn%5===0)addLog(`Year ${Math.ceil(state.turn/5)} turns toward a new season.`);
 if(state.turn===MAX_TURNS){finishGame();return;}state.turn++;state.orders=2;addLog(`A new day dawns. <strong>Turn ${state.turn}</strong> begins.`);render();if(state.turn===2)showToast('Your people have a full day ahead. Build, explore, and grow!');}
function finishGame(){state.done=true;const cities=state.map.flat().filter(t=>t.city),pop=cities.reduce((n,t)=>n+t.city.pop,0),improvements=state.map.flat().filter(t=>t.improvement).length;state.score=cities.length*100+pop*18+improvements*12+state.resources.coin*4;
 let title=state.score>=480?'A flourishing little empire!':state.score>=300?'A kingdom with promise!':'A humble beginning.';let medal=state.score>=480?'👑':state.score>=300?'🏆':'🌱';$('modalContent').innerHTML=`<div class="medal">${medal}</div><div class="eyebrow">YOUR 20-TURN STORY</div><h2>${title}</h2><p>Your people built ${cities.length} ${cities.length===1?'town':'towns'}, grew to ${pop} people, and tended ${improvements} improvements. Every kingdom starts somewhere.</p><div class="score">KINGDOM SCORE &nbsp; ${state.score}</div><button id="playAgain">Begin a new story</button>`;$('modal').classList.add('show');$('playAgain').onclick=restart;render();}
function restart(){state=freshState();$('modal').classList.remove('show');addLog('A new story begins in a bright little valley.');render();showToast('A fresh world awaits!');}
$('endTurn').addEventListener('click',endTurn);$('restartBtn').addEventListener('click',()=>{if(confirm('Start a new kingdom from turn one?'))restart()});$('clearLog').addEventListener('click',()=>{state.log=[];render()});$('soundBtn').addEventListener('click',e=>{state.sound=!state.sound;e.currentTarget.textContent=state.sound?'♫':'♪';showToast(state.sound?'Birdsong enabled (just in spirit).':'Sound muted.');});
// Add a move order to any empty tile next to one of your wandering units.
const oldActionMarkup=actionMarkup;
actionMarkup=function(){oldActionMarkup();const t=selectedTile(),u=unitOn(t),adjacent=state.units.filter(q=>Math.abs(q.x-t.x)+Math.abs(q.y-t.y)===1);if(!u&&t.code!=='W'&&adjacent.length&&rangeToCity(t)<=2&&!t.city){const holder=$('actionCard').querySelector('.action-list');if(holder){for(const unit of adjacent){const btn=document.createElement('button');btn.className='action-btn';btn.disabled=!canOrder();btn.innerHTML=`<span class="action-icon">➜</span><span class="action-text"><b>Move ${names[unit.type].toLowerCase()}</b><small>Step onto this tile</small></span><span class="cost">1 order</span>`;btn.addEventListener('click',()=>{unit.x=t.x;unit.y=t.y;addLog(`Your <strong>${names[unit.type].toLowerCase()}</strong> ventured to new ground.`);useOrder()});holder.insertBefore(btn,holder.firstChild);}}}};
addLog('A new story begins in a bright little valley.');render();
</script></body></html>

