Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -13,4 +13,23 @@
 <section class="card action-card" id="actionCard"></section><button class="end-btn" id="endTurn"><span>End turn &nbsp;→</span><small id="turnHint">2 ORDERS LEFT</small></button>
 <section class="card log-card"><div class="log-head"><div class="section-title">Kingdom chronicle</div><button id="clearLog">clear</button></div><ul class="log" id="log"></ul></section></aside></main></div>
 <div class="toast" id="toast" role="status"></div><div class="modal-backdrop" id="modal"><div class="modal" id="modalContent"></div></div>
 <script>
+const W=10,H=10,MAX_TURNS=20;
+const terrainRows=['MMHFGGFHMM','MHFGGWGFHM','HFGFGWGFGH','FGGHFWFHGF','GFHGGGGFGG','GGGFGGHGGF','HGFGWGGHFG','FGGGWGFGGH','HFGGGFGGHM','MHFGGGFHMM'];
+const terrainInfo={G:{name:'Meadow',icon:'🌿',cls:'grass',yield:'🌾 +1 food',food:1},F:{name:'Forest',icon:'🌲',cls:'forest',yield:'🪵 +1 wood',wood:1},H:{name:'Rolling hills',icon:'⛰️',cls:'hill',yield:'🪨 +1 stone',stone:1},M:{name:'High mountains',icon:'🏔️',cls:'mountain',yield:'🪨 +1 stone',stone:1},W:{name:'River',icon:'💧',cls:'water',yield:'🌾 +1 food',food:1},S:{name:'Sunny plain',icon:'🌾',cls:'sand',yield:'🪙 +1 coin',coin:1},X:{name:'Marsh',icon:'🪷',cls:'marsh',yield:'🌾 +1 food',food:1}};
+function freshState(){const map=terrainRows.map((row,y)=>row.split('').map((code,x)=>({x,y,code,improvement:null,city:null})));map[5][4].city={name:'Crownstead',pop:2,level:1};return{map,turn:1,orders:2,resources:{food:8,wood:6,stone:4,coin:3},units:[{type:'settler',x:4,y:4},{type:'scout',x:3,y:5}],selected:{x:4,y:4},log:[],done:false,score:0};}
+let state=freshState();const $=id=>document.getElementById(id),at=(x,y)=>state.map[y]?.[x];let handlers=[];
+function addLog(text){state.log.unshift({turn:state.turn,text});state.log=state.log.slice(0,6)}function showToast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),2100)}
+function isOwned(tile){return state.map.some(row=>row.some(c=>c.city&&Math.abs(c.x-tile.x)+Math.abs(c.y-tile.y)<=2))}function unitOn(tile,type){return state.units.find(u=>u.x===tile.x&&u.y===tile.y&&(!type||u.type===type))}function selectedTile(){return at(state.selected.x,state.selected.y)}function rangeToCity(tile){let best=99;for(const row of state.map)for(const c of row)if(c.city)best=Math.min(best,Math.abs(c.x-tile.x)+Math.abs(c.y-tile.y));return best}
+function canPay(cost){return Object.entries(cost).every(([k,v])=>state.resources[k]>=v)}function pay(cost){Object.entries(cost).forEach(([k,v])=>state.resources[k]-=v)}function canOrder(){return state.orders>0&&!state.done}
+function act(label,icon,desc,cost,enabled,fn){const i=handlers.push(fn)-1;return `<button class="action-btn" ${enabled?'':'disabled'} data-i="${i}"><span class="action-icon">${icon}</span><span class="action-text"><b>${label}</b><small>${desc}</small></span><span class="cost">${Object.entries(cost||{}).map(([k,v])=>`${({food:'🌾',wood:'🪵',stone:'🪨',coin:'🪙'})[k]}${v}`).join(' ')||'1 order'}</span></button>`;}
+function useOrder(){state.orders=Math.max(0,state.orders-1);render()}
+function renderMap(){const grid=$('mapGrid');grid.innerHTML='';for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=at(x,y),btn=document.createElement('button');btn.className='tile '+(t.city?'city-tile':terrainInfo[t.code].cls)+((state.selected.x===x&&state.selected.y===y)?' selected':'');btn.setAttribute('role','gridcell');btn.setAttribute('aria-label',`${t.city?t.city.name:terrainInfo[t.code].name}, ${x+1}, ${y+1}`);const icon=t.city?'🏘️':terrainInfo[t.code].icon,unit=unitOn(t);btn.innerHTML=`<span class="terrain">${icon}</span>${t.city?`<span class="badge">${t.city.pop}👤</span>`:''}${t.improvement?`<span class="deco">${t.improvement.icon}</span>`:''}${unit?`<i class="unit-dot ${unit.type==='scout'?'scout':''}"></i>`:''}`;btn.addEventListener('click',()=>{state.selected={x,y};render()});grid.appendChild(btn)}}
+function actionMarkup(){handlers=[];const t=selectedTile(),base=terrainInfo[t.code],u=unitOn(t),near=rangeToCity(t)<=2,adjacent=state.units.filter(q=>Math.abs(q.x-t.x)+Math.abs(q.y-t.y)===1),pieces=[];let title=t.city?t.city.name:base.name,sub=t.city?`Your town · Level ${t.city.level}`:t.improvement?`${t.improvement.name} · ${base.name}`:base.yield;
